Códigoroutes &lt;- read_csv(fs::path(ruta_datos, "routes.txt"))
trips  &lt;- read_csv(fs::path(ruta_datos, "trips.txt"))
stops  &lt;- read_csv(fs::path(ruta_datos, "stops.txt"), 
                   col_types = cols(stop_url = col_character()))

